#!/usr/bin/env python3
"""Tiny direct-manipulation controller for generic structured cover pages."""
JS=r'''<script id="d2-cover-interaction">(()=>{const page='multiwrite-cover',canvas=document.querySelector('.canvas');if(!canvas)return;let sel=null,drag=null;const box=document.createElement('div');box.id='d2-selection';canvas.appendChild(box);function rect(){if(!sel){box.hidden=true;return}box.hidden=false;Object.assign(box.style,{left:sel.offsetLeft+'px',top:sel.offsetTop+'px',width:sel.offsetWidth+'px',height:sel.offsetHeight+'px'})}function pick(n){sel=n;rect();parent.postMessage({type:'dore-select',page_id:page,id:n.dataset.id,field:'text',value:n.innerText},'*');parent.postMessage({type:'dore-selection-set',page_id:page,ids:[n.dataset.id],primary:n.dataset.id},'*')}async function save(){if(!sel)return;const patch={x:sel.offsetLeft,y:sel.offsetTop,w:sel.offsetWidth};if(sel.offsetHeight)patch.h=sel.offsetHeight;const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'set_node',page_id:page,id:sel.dataset.id,patch})});parent.postMessage({type:r.ok?'dore-saved':'dore-error',page_id:page},'*')}canvas.addEventListener('pointerdown',e=>{const n=e.target.closest('[data-id]');if(!n)return;e.preventDefault();pick(n);drag={x:e.clientX,y:e.clientY,l:n.offsetLeft,t:n.offsetTop};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag||!sel)return;sel.style.left=Math.round(drag.l+e.clientX-drag.x)+'px';sel.style.top=Math.round(drag.t+e.clientY-drag.y)+'px';rect()});canvas.addEventListener('pointerup',()=>{if(!drag)return;drag=null;save()});addEventListener('keydown',e=>{if(!sel||['INPUT','TEXTAREA'].includes(e.target.tagName))return;let s=e.shiftKey?10:1,dx=0,dy=0;if(e.key==='ArrowLeft')dx=-s;if(e.key==='ArrowRight')dx=s;if(e.key==='ArrowUp')dy=-s;if(e.key==='ArrowDown')dy=s;if(!dx&&!dy)return;e.preventDefault();sel.style.left=sel.offsetLeft+dx+'px';sel.style.top=sel.offsetTop+dy+'px';rect();save()})})()</script>'''
CSS='''<style>#d2-selection{position:absolute;z-index:9998;border:1px solid #b49a55;pointer-events:none}#d2-selection[hidden]{display:none}</style>'''
def augment(html):return html.replace('</head>',CSS+'</head>',1).replace('</body>',JS+'</body>',1)
